// ComfyUI's partner nodes, which call a hosted model, read from a frozen
// table (partner-nodes.json, regenerated by scripts/comfy-partner-map.mjs)
// rather than guessed from their names. The table says what a node makes,
// whose model it calls and which media it takes; this module turns that into
// the native step it becomes, or the reason it has none.

import type { VideoDirection } from "../../catalog";
import table from "./partner-nodes.json";

interface PartnerEntry {
  makes: "video" | "image" | "audio" | "text" | "3d" | "svg" | "mask" | "other";
  provider: string;
  /** Media inputs as "kind:name" ("image:first_frame"). */
  takes: string[];
}

export type PartnerRole =
  | { kind: "video"; provider: string; direction?: VideoDirection }
  | {
      kind: "image" | "imageEdit" | "upscale" | "cutout" | "tts" | "music" | "chat";
      provider: string;
    }
  | { kind: "none"; provider: string; makes: "3d" | "svg" | "voice" | "helper" };

const PARTNERS = table as Record<string, PartnerEntry>;

export function knownPartner(type: string): boolean {
  return Object.hasOwn(PARTNERS, type);
}

export function partnerRole(type: string): PartnerRole | undefined {
  const entry = PARTNERS[type];
  if (!entry) return undefined;
  const { provider } = entry;
  const takes = (kind: string) => entry.takes.filter((input) => input.startsWith(`${kind}:`));
  switch (entry.makes) {
    case "video": {
      if (takes("video").length > 0) return { kind: "video", provider, direction: "video" };
      const images = takes("image");
      if (
        images.some((input) => /reference|ref_/i.test(input)) &&
        !images.some((input) => /first|start/i.test(input))
      )
        return { kind: "video", provider, direction: "reference" };
      if (images.length > 0) return { kind: "video", provider, direction: "image" };
      // No picture input it names: the links in the file decide.
      return { kind: "video", provider };
    }
    case "image":
      if (/upscal|enhanc|crystal|sharpen/i.test(type)) return { kind: "upscale", provider };
      if (/remove.*background|background.*remov|rembg/i.test(type))
        return { kind: "cutout", provider };
      // A picture input is often optional (a reference): the links in the
      // file tell a generation from an edit.
      return { kind: "image", provider };
    case "audio":
      // A recording turned into another voice: Sub Rosa reads text aloud,
      // it does not change a voice.
      if (takes("audio").length > 0) return { kind: "none", provider, makes: "voice" };
      if (/sound|sfx|effect|music|song/i.test(type)) return { kind: "music", provider };
      return { kind: "tts", provider };
    case "text":
      return { kind: "chat", provider };
    case "3d":
    case "svg":
      return { kind: "none", provider, makes: entry.makes };
    default:
      return { kind: "none", provider, makes: "helper" };
  }
}
